// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Capability self-description
	// (GET /api/v1)
	GetCapabilities(c *gin.Context)
	// List BIOS baseline profiles
	// (GET /api/v1/bios-profiles)
	ListBiosProfiles(c *gin.Context)
	// Create a BIOS baseline profile
	// (POST /api/v1/bios-profiles)
	CreateBiosProfile(c *gin.Context)
	// Delete a profile
	// (DELETE /api/v1/bios-profiles/{id})
	DeleteBiosProfile(c *gin.Context, id ProfileId)
	// Fetch one profile
	// (GET /api/v1/bios-profiles/{id})
	GetBiosProfile(c *gin.Context, id ProfileId)
	// Fan the profile's attributes out as one batch job
	// (POST /api/v1/bios-profiles/{id}/apply)
	ApplyBiosProfile(c *gin.Context, id ProfileId)
	// Effective configuration snapshot (redacted)
	// (GET /api/v1/config)
	GetConfig(c *gin.Context)
	// List credentials (metadata only, newest first)
	// (GET /api/v1/credentials)
	ListCredentials(c *gin.Context)
	// Register a credential
	// (POST /api/v1/credentials)
	CreateCredential(c *gin.Context, params CreateCredentialParams)
	// Delete a credential
	// (DELETE /api/v1/credentials/{id})
	DeleteCredential(c *gin.Context, id CredentialId)
	// Get credential metadata (never the secret)
	// (GET /api/v1/credentials/{id})
	GetCredential(c *gin.Context, id CredentialId)
	// Query events (audit and SSE backlog)
	// (GET /api/v1/events)
	ListEvents(c *gin.Context, params ListEventsParams)
	// Stream all events (SSE)
	// (GET /api/v1/events/stream)
	StreamEvents(c *gin.Context, params StreamEventsParams)
	// List registered images (newest first)
	// (GET /api/v1/images)
	ListImages(c *gin.Context)
	// Register an image artifact and start the fetch
	// (POST /api/v1/images)
	CreateImage(c *gin.Context)
	// Delete an image registration
	// (DELETE /api/v1/images/{id})
	DeleteImage(c *gin.Context, id string)
	// Get one image registration
	// (GET /api/v1/images/{id})
	GetImage(c *gin.Context, id string)
	// Fetch the cached image file (machine face)
	// (GET /api/v1/images/{id}/file)
	FetchImageFile(c *gin.Context, id string)
	// List jobs
	// (GET /api/v1/jobs)
	ListJobs(c *gin.Context, params ListJobsParams)
	// Submit a job (batch install / power / discover)
	// (POST /api/v1/jobs)
	CreateJob(c *gin.Context, params CreateJobParams)
	// Get a job with its summary
	// (GET /api/v1/jobs/{id})
	GetJob(c *gin.Context, id JobId)
	// Cancel a job
	// (POST /api/v1/jobs/{id}/cancel)
	CancelJob(c *gin.Context, id JobId)
	// Stream a job's events (SSE)
	// (GET /api/v1/jobs/{id}/events)
	StreamJobEvents(c *gin.Context, id JobId, params StreamJobEventsParams)
	// List tasks of a job
	// (GET /api/v1/jobs/{id}/tasks)
	ListJobTasks(c *gin.Context, id JobId, params ListJobTasksParams)
	// Get a task with its stage details
	// (GET /api/v1/jobs/{id}/tasks/{taskId})
	GetJobTask(c *gin.Context, id JobId, taskId TaskId)
	// Task execution logs
	// (GET /api/v1/jobs/{id}/tasks/{taskId}/logs)
	ListJobTaskLogs(c *gin.Context, id JobId, taskId TaskId, params ListJobTaskLogsParams)
	// Stream task execution logs (SSE)
	// (GET /api/v1/jobs/{id}/tasks/{taskId}/logs/stream)
	StreamJobTaskLogs(c *gin.Context, id JobId, taskId TaskId, params StreamJobTaskLogsParams)
	// Retry a failed or interrupted task
	// (POST /api/v1/jobs/{id}/tasks/{taskId}/retry)
	RetryJobTask(c *gin.Context, id JobId, taskId TaskId)
	// List machines
	// (GET /api/v1/machines)
	ListMachines(c *gin.Context, params ListMachinesParams)
	// Register a machine by its out-of-band address and credential
	// (POST /api/v1/machines)
	CreateMachine(c *gin.Context, params CreateMachineParams)
	// Apply one label add/remove set to many machines
	// (POST /api/v1/machines/batch-labels)
	BatchUpdateMachineLabels(c *gin.Context, params BatchUpdateMachineLabelsParams)
	// Deregister a machine
	// (DELETE /api/v1/machines/{id})
	DeleteMachine(c *gin.Context, id MachineId)
	// Get a machine
	// (GET /api/v1/machines/{id})
	GetMachine(c *gin.Context, id MachineId)
	// Update mutable machine fields
	// (PATCH /api/v1/machines/{id})
	UpdateMachine(c *gin.Context, id MachineId)
	// Latest post-install acceptance report
	// (GET /api/v1/machines/{id}/acceptance)
	GetMachineAcceptance(c *gin.Context, id MachineId)
	// Dispatch a single-machine out-of-band action
	// (POST /api/v1/machines/{id}/actions)
	PerformMachineAction(c *gin.Context, id MachineId, params PerformMachineActionParams)
	// Live BIOS attribute table
	// (GET /api/v1/machines/{id}/bios)
	GetMachineBios(c *gin.Context, id MachineId)
	// Assign (or clear) the machine's BIOS baseline profile
	// (PUT /api/v1/machines/{id}/bios/baseline)
	SetMachineBiosBaseline(c *gin.Context, id MachineId)
	// Live BIOS attributes held against the assigned baseline
	// (GET /api/v1/machines/{id}/bios/drift)
	GetMachineBiosDrift(c *gin.Context, id MachineId)
	// Get a one-time KVM / virtual console URL
	// (GET /api/v1/machines/{id}/console)
	GetMachineConsole(c *gin.Context, id MachineId)
	// List the machine's unfinished tasks
	// (GET /api/v1/machines/{id}/current-tasks)
	ListMachineCurrentTasks(c *gin.Context, id MachineId)
	// Latest decommission evidence report
	// (GET /api/v1/machines/{id}/decommission)
	GetMachineDecommission(c *gin.Context, id MachineId)
	// Live physical drive table of the controller
	// (GET /api/v1/machines/{id}/drives)
	GetMachineDrives(c *gin.Context, id MachineId)
	// Live health snapshot of the controller
	// (GET /api/v1/machines/{id}/health)
	GetMachineHealth(c *gin.Context, id MachineId)
	// Resolve an install spec into a plan without installing
	// (POST /api/v1/machines/{id}/install-plan)
	CreateInstallPlan(c *gin.Context, id MachineId)
	// Get the latest disk layout snapshot
	// (GET /api/v1/machines/{id}/layout)
	GetMachineLayout(c *gin.Context, id MachineId)
	// Live logical-drive table of the controller with the free drive pool
	// (GET /api/v1/machines/{id}/raid)
	GetMachineRaid(c *gin.Context, id MachineId)
	// Live system event log of the controller
	// (GET /api/v1/machines/{id}/sel)
	GetMachineSEL(c *gin.Context, id MachineId)
	// List zero-registration PXE sightings
	// (GET /api/v1/pending-machines)
	ListPendingMachines(c *gin.Context)
	// Remove a sighting (manual dismiss)
	// (DELETE /api/v1/pending-machines/{mac})
	DeletePendingMachine(c *gin.Context, mac string)
	// One zero-registration sighting by MAC
	// (GET /api/v1/pending-machines/{mac})
	GetPendingMachine(c *gin.Context, mac string)
	// Promote a zero-registration sighting to a registered machine
	// (POST /api/v1/pending-machines/{mac}/claim)
	ClaimPendingMachine(c *gin.Context, mac string, params ClaimPendingMachineParams)
	// List webhook subscriptions (no secrets)
	// (GET /api/v1/webhooks)
	ListWebhooks(c *gin.Context)
	// Subscribe an HTTP endpoint to events
	// (POST /api/v1/webhooks)
	CreateWebhook(c *gin.Context, params CreateWebhookParams)
	// Delete a webhook subscription
	// (DELETE /api/v1/webhooks/{id})
	DeleteWebhook(c *gin.Context, id string)
	// Get a webhook subscription (no secret)
	// (GET /api/v1/webhooks/{id})
	GetWebhook(c *gin.Context, id string)
	// Liveness probe (no dependency checks)
	// (GET /healthz)
	Healthz(c *gin.Context)
	// Fetch a shared enrollment boot tree file
	// (GET /netboot/enroll-file/{name})
	FetchNetbootEnrollFile(c *gin.Context, name string)
	// Submit zero-registration enrollment findings
	// (POST /netboot/enroll/{token})
	ReportEnrollment(c *gin.Context, token string, params ReportEnrollmentParams)
	// Fetch a network boot tree file by task token
	// (GET /netboot/files/{token}/{file})
	FetchNetbootFile(c *gin.Context, token string, file string)
	// iPXE boot script for a client MAC
	// (GET /netboot/script)
	GetNetbootScript(c *gin.Context, params GetNetbootScriptParams)
	// Readiness probe (database and queue reachable)
	// (GET /readyz)
	Readyz(c *gin.Context)
	// Report install completion from the target machine
	// (POST /render/{token}/complete)
	ReportInstallComplete(c *gin.Context, token string)
	// Submit ramdisk probe findings
	// (POST /render/{token}/probe-report)
	ReportProbeFindings(c *gin.Context, token string)
	// Fetch a rendered answer file by task token
	// (GET /render/{token}/{file})
	FetchAnswerFile(c *gin.Context, token string, file string)
}

